const byCode = new Map(EDGAR_COUNTRIES.map((country) => [country.code.toUpperCase(), country]));

function normalizeCountryName(value) {
  return String(value ?? "")
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .toLowerCase()
    .replace(/&/g, " and ")
    .replace(/[^a-z0-9]+/g, " ")
    .trim()
    .replace(/\s+/g, " ");
}

const aliases = {
  "usa": "USA",
  "united states of america": "USA",
  "u s": "USA",
  "russian federation": "RUS",
  "russia": "RUS",
  "vietnam": "VNM",
  "czech republic": "CZE",
  "ivory coast": "CIV",
  "cote d ivoire": "CIV",
  "gambia": "GMB",
  "the gambia": "GMB",
  "south korea": "KOR",
  "republic of korea": "KOR",
  "north korea": "PRK",
  "democratic people s republic of korea": "PRK",
  "burma": "MMR",
  "myanmar": "MMR",
  "turkey": "TUR",
  "swaziland": "SWZ",
  "cape verde": "CPV",
  "east timor": "TLS",
  "curacao": "ANT",
  "brunei darussalam": "BRN",
  "lao people s democratic republic": "LAO",
  "bolivia plurinational state of": "BOL",
  "venezuela bolivarian republic of": "VEN",
  "tanzania united republic of": "TZA",
  "moldova republic of": "MDA",
  "iran islamic republic of": "IRN"
};

const byName = new Map(
  EDGAR_COUNTRIES.map((country) => [normalizeCountryName(country.name), country])
);

function readCandidateValues(location) {
  if (typeof location === "string" || typeof location === "number") {
    return [String(location)];
  }
  if (!location || typeof location !== "object") return [];

  const properties = location.properties && typeof location.properties === "object"
    ? location.properties
    : {};

  return [
    location.edgarCode,
    location.countryCode,
    location.code,
    location.iso_a3,
    location.ISO_A3,
    location.ADM0_A3,
    location.country_code,
    location.name,
    location.countryName,
    location.country,
    location.label,
    properties.edgarCode,
    properties.countryCode,
    properties.iso_a3,
    properties.ISO_A3,
    properties.ADM0_A3,
    properties.country_code,
    properties.name,
    properties.NAME,
    properties.NAME_EN,
    properties.ADMIN,
    properties.name_en
  ].filter((value) => value !== undefined && value !== null && String(value).trim());
}

export function getEdgarCountryProfile(location) {
  const candidates = readCandidateValues(location);

  for (const candidate of candidates) {
    const raw = String(candidate).trim();
    const codeMatch = byCode.get(raw.toUpperCase());
    if (codeMatch) return buildProfile(codeMatch);

    const normalized = normalizeCountryName(raw);
    const aliasCode = aliases[normalized];
    if (aliasCode && byCode.has(aliasCode)) {
      return buildProfile(byCode.get(aliasCode));
    }

    const nameMatch = byName.get(normalized);
    if (nameMatch) return buildProfile(nameMatch);
  }

  return null;
}

function buildProfile(country) {
  const emissions = country.annualEmissionsMtCO2e;
  const index2020 = EDGAR_YEARS.indexOf(2020);
  const index2025 = EDGAR_YEARS.indexOf(2025);
  const value2020 = emissions[index2020];
  const latest = emissions[index2025];
  const changeSince2020Percent =
    Number.isFinite(value2020) && value2020 !== 0 && Number.isFinite(latest)
      ? ((latest - value2020) / value2020) * 100
      : null;

  return {
    ...country,
    years: EDGAR_YEARS,
    latestYear: 2025,
    latestEmissionsMtCO2e: latest,
    changeSince2020Percent,
    source: EDGAR_SOURCE
  };
}

export { EDGAR_SOURCE, EDGAR_YEARS, EDGAR_COUNTRIES };
